	ENEMY_ROLL_DURATION_MIN_MS,
	ENEMY_ROLL_INTERVAL_MAX_MS,
	ENEMY_ROLL_INTERVAL_MIN_MS,
	ENEMY_SPAWN_INTERVAL_MS,
	ENEMY_SPEED,
	FIRE_COOLDOWN_MS,
	HIT_RADIUS,
	INVULN_BLINK_MS,
	INVULN_MS,
