	// app gets a Camera3d as its default camera (the loader screen pins
	// to Camera2d via its own constructor regardless).
	const app = new Application(1024, 768, {
		parent: "screen",
		renderer: video.AUTO,
		scale: "auto",
		cameraClass: Camera3dClass,
	});
