			const x1 = cx + sx / 2;
			const z0 = cz - sz / 2;
			const z1 = cz + sz / 2;

			// ── walls (4 sides + flat roof) ────────────────────────────────────
			quad(walls, x0, 0, z1, sx, 0, 0, 0, sy, 0, 0, 0, 1); // +Z
			quad(walls, x1, 0, z0, -sx, 0, 0, 0, sy, 0, 0, 0, -1); // -Z
			quad(walls, x1, 0, z1, 0, 0, -sz, 0, sy, 0, 1, 0, 0); // +X
			quad(walls, x0, 0, z0, 0, 0, sz, 0, sy, 0, -1, 0, 0); // -X
