import {
	audio,
	Collectable,
	collision,
	Ellipse,
	event,
	game,
	ShineEffect,
	timer,
} from "melonjs";
import { gameState } from "../gameState";

// Per-instance shine shader. Pool-recycled (recycle:true) so
// onDestroyEvent doesn't fire on pickup — bind GAME_UPDATE on
// activate, unbind on deactivate.

export class CoinEntity extends Collectable {
	private shineShader: ShineEffect | undefined;
	private shineUpdateHandler: (() => void) | undefined;
	private shineSubscribed = false;

	/**
	 * constructor
	 */
	constructor(x, y, _settings) {
		// call the super constructor
		super(
			x,
			y,
			Object.assign({
				image: gameState.texture,
				region: "coin.png",
				shapes: [new Ellipse(35 / 2, 35 / 2, 35, 35)], // coins are 35x35
			}),
		);
		// shader + subscription deferred to onActivateEvent
	}

	private attachShine(): boolean {
		if (this.shineShader) return true;
		const renderer = this.parentApp?.renderer;
		if (!renderer) return false;
		this.shineShader = new ShineEffect(renderer, {
			color: [1.0, 0.95, 0.7], // warm white-gold highlight
			speed: 0.8,
			width: 0.25, // wider, gentler glint
			intensity: 0.22, // softer highlight
			angle: 0.35, // slight diagonal sweep (~20°)
			bands: 14.5, // ~14 parallel etched-rim glints
			pulseDepth: 0.04, // very subtle brightness pulse
		});
		this.shineUpdateHandler = () => {
			this.shineShader?.setTime(timer.getTime() / 1000.0);
		};
		this.addPostEffect(this.shineShader);
		return true;
	}

	private subscribeShine() {
		if (this.shineSubscribed || !this.shineUpdateHandler) return;
		event.on(event.GAME_UPDATE, this.shineUpdateHandler);
		this.shineSubscribed = true;
	}

	private unsubscribeShine() {
		if (!this.shineSubscribed || !this.shineUpdateHandler) return;
		event.off(event.GAME_UPDATE, this.shineUpdateHandler);
		this.shineSubscribed = false;
	}

	onActivateEvent() {
		super.onActivateEvent();
		if (this.attachShine()) {
			this.subscribeShine();
		} else {
			// renderer not ready yet — defer to LEVEL_LOADED
			event.once(event.LEVEL_LOADED, () => {
				if (this.attachShine()) {
					this.subscribeShine();
				}
			});
		}
	}

	onDeactivateEvent() {
		this.unsubscribeShine();
		super.onDeactivateEvent();
	}

	// called by the pool on object recycling
	onResetEvent(x, y, _settings) {
		this.shift(x, y);
		// only check for collision against player
		this.body.setCollisionMask(collision.types.PLAYER_OBJECT);
	}

	/**
	 * collision handling
	 */
	onCollision(/*response*/) {
		// do something when collide
		audio.play("cling", false);
		// give some score
		gameState.data.score += 250;

		//avoid further collision and delete it
		this.body.setCollisionMask(collision.types.NO_OBJECT);

		game.world.removeChild(this);

		return false;
	}

	onDestroyEvent() {
		// fires only on real destroy (level reset / app shutdown)
		this.unsubscribeShine();
		this.shineShader = undefined;
		this.shineUpdateHandler = undefined;
	}
}
`,De=`/**
 * melonJS — Platformer (built-in SAT physics) example.
 * Copyright (C) 2011 - 2026 AltByte Pte Ltd — MIT License.
 * See \`packages/examples/LICENSE.md\` for full license + asset credits.
 */
import {
	Container,
	event,
	game,
	input,
	Sprite,
	UISpriteElement,
	Vector2d,
} from "melonjs";
import { gameState } from "../gameState";

/**
 * a basic control to toggle fullscreen on/off
 */
class Button extends UISpriteElement {
	/**
	 * constructor
	 */
	constructor(x, y) {
		super(x, y, {
			image: gameState.texture,
			region: "shadedDark36.png",
		});
		this.setOpacity(0.25);
		this.anchorPoint.set(0, 0);
	}

	/**
	 * function called when the object is clicked on
	 */
	onClick(_event) {
		this.setOpacity(0.5);
		input.triggerKeyEvent(input.KEY.SPACE, true);
		return false;
	}

	/**
	 * function called when the object is clicked on
	 */
	onRelease(_event) {
		this.setOpacity(0.25);
		input.triggerKeyEvent(input.KEY.SPACE, false);
		return false;
	}
}

/**
 * a virtual joypad
 */
class Joypad extends UISpriteElement {
	/**
	 * constructor
	 */
	constructor(x, y) {
		super(x, y, {
			// background "fix" part of the joypad
			image: gameState.texture,
			region: "shadedDark07.png",
			anchorPoint: new Vector2d(0, 0),
		});

		// mobile part of the joypad
		this.pad = new Sprite(x, y, {
			image: gameState.texture,
			region: "shadedDark01.png",
			anchorPoint: new Vector2d(0, 0),
		});

		// default relative position from the back of the joypad
		this.relative = new Vector2d(
			this.width / 2 - this.pad.width / 2,
			this.height / 2 - this.pad.height / 2,
		);

		// offset by which the joypad move when pressed/moved
		this.joypad_offset = new Vector2d();

		// default opacity
		this.setOpacity(0.25);

		// cursors status
		// TODO make it configurable
		this.cursors = {
			up: false,
			down: false,
			left: false,
			right: false,
		};

		// register on the pointermove event
		input.registerPointerEvent(
			"pointermove",
			this,
			this.pointerMove.bind(this),
		);
	}

	onDestroyEvent() {
		// release register event event
		input.releasePointerEvent("pointermove", this);
	}

	/**
	 * pointermove function
	 */
	pointerMove(event) {
		if (this.released === false) {
			const x = event.gameScreenX + event.width / 2;
			const y = event.gameScreenY + event.height / 2;
			// pointerMove is a global on the viewport, so check for coordinates
			if (this.getBounds().contains(x, y)) {
				// if any direction is active, update it if necessary
				if (this.cursors.left === true || this.cursors.right === true) {
					this.checkDirection.call(this, x, y);
				}
			} else {
				// release keys/joypad if necessary
				this.onRelease.call(this, event);
			}
		}
	}

	// update the cursors value and trigger key event
	checkDirection(x, _y) {
		if (x - this.pos.x < this.width / 2) {
			if (this.cursors.left === false) {
				input.triggerKeyEvent(input.KEY.LEFT, true);
				this.cursors.left = true;
				this.joypad_offset.x = -(
					((this.width / 2 - (x - this.pos.x)) % this.pad.width) /
					4
				);
			}
			// release the right key if it was pressed
			if (this.cursors.right === true) {
				input.triggerKeyEvent(input.KEY.RIGHT, false);
				this.cursors.right = false;
			}
		}
		if (x - this.pos.x > this.width / 2) {
			if (this.cursors.right === false) {
				input.triggerKeyEvent(input.KEY.RIGHT, true);
				this.cursors.right = true;
				this.joypad_offset.x = +(
					((x - this.pos.x - this.width / 2) % this.pad.width) /
					4
				);
			}
			// release the left key is it was pressed
			if (this.cursors.left === true) {
				input.triggerKeyEvent(input.KEY.LEFT, false);
				this.cursors.left = false;
			}
		}
	}

	/**
	 * function called when the object is clicked on
	 */
	onClick(event) {
		const x = event.gameScreenX + event.width / 2;
		const y = event.gameScreenY + event.height / 2;
		this.setOpacity(0.5);
		this.checkDirection.call(this, x, y);
		return false;
	}

	/**
	 * function called when the object is release or cancelled
	 */
	onRelease(_event) {
		this.setOpacity(0.25);
		if (this.cursors.left === true) {
			input.triggerKeyEvent(input.KEY.LEFT, false);
			this.cursors.left = false;
		}
		if (this.cursors.right === true) {
			input.triggerKeyEvent(input.KEY.RIGHT, false);
			this.cursors.right = false;
		}
		this.joypad_offset.set(0, 0);
		return false;
	}

	/**
	 * extend the draw function
	 */
	draw(renderer) {
		// call the super constructor
		super.draw(renderer);
		this.pad.pos.setV(this.pos).add(this.relative).add(this.joypad_offset);
		this.pad.draw(renderer);
	}
}

/**
 * a very simple virtual joypad and buttons, that triggers
 * corresponding key events
 */
export class VirtualJoypad extends Container {
	constructor() {
		// call the constructor
		super();

		// persistent across level change
		this.isPersistent = true;

		// Use screen coordinates
		this.floating = true;

		// make sure our object is always draw first
		this.z = Number.POSITIVE_INFINITY;

		// give a name
		this.name = "VirtualJoypad";

		// instance of the virtual joypad
		this.joypad = new Joypad(50, game.viewport.height - 200);

		// instance of the button
		this.button = new Button(
			game.viewport.width - 150,
			game.viewport.height - 150,
		);

		this.addChild(this.joypad);
		this.addChild(this.button);

		event.on(event.VIEWPORT_ONRESIZE, (width, height) => {
			this.button.pos.set(width - 150, height - 150, this.button.pos.z);
		});
	}
}
