import { Camera2d, event, game, level, VignetteEffect } from "melonjs";

const MINIMAP_WIDTH = 180;
const MINIMAP_HEIGHT = 100;

/**
 * A minimap camera that shows a zoomed-out view of the entire level
 * in the top-right corner of the screen.
 */
export class MinimapCamera extends Camera2d {
	private boundOnResize: (w: number) => void;

	constructor() {
		super(0, 0, MINIMAP_WIDTH, MINIMAP_HEIGHT);
		this.name = "minimap";
		this.screenX = game.viewport.width - MINIMAP_WIDTH - 10;
		this.screenY = 10;

		// prevent canvas resize from resetting this camera's dimensions/bounds
		this.autoResize = false;

		// reposition on canvas resize (keep anchored to top-right)
		this.boundOnResize = (w: number) => {
			this.screenX = w - MINIMAP_WIDTH - 10;
		};
		event.on(event.CANVAS_ONRESIZE, this.boundOnResize);

		// apply subtle vignette post-process effect on the minimap
		this.addPostEffect(new VignetteEffect(game.renderer));

		const currentLevel = level.getCurrentLevel();
		if (currentLevel) {
			const lw = currentLevel.cols * currentLevel.tilewidth;
			const lh = currentLevel.rows * currentLevel.tileheight;
			this.setBounds(0, 0, lw, lh);
			this.zoom = Math.min(MINIMAP_WIDTH / lw, MINIMAP_HEIGHT / lh);
		}
	}

	/**
	 * Draw minimap overlays: viewport highlight, player marker, and border.
	 */
	// biome-ignore lint/suspicious/noExplicitAny: renderer type varies between WebGL/Canvas
	override postDraw(renderer: any): void {
		const viewport = game.viewport;
		const screenPx = 1 / this.zoom; // 1 screen pixel in world units
		const savedLineWidth = renderer.lineWidth;

		// main camera's visible area in world space
		const view = viewport.worldView;
		renderer.setGlobalAlpha(0.9);
		renderer.setColor("#ffffff");
		renderer.lineWidth = 1.5 * screenPx;
		renderer.strokeRect(view.left, view.top, view.width, view.height);

		// player position marker
		const players = game.world.getChildByProp("name", "mainPlayer");
		if (players.length > 0) {
			const player = players[0];
			const markerSize = 4 * screenPx;
			renderer.setGlobalAlpha(1.0);
			renderer.setColor("#00ff00");
			renderer.fillEllipse(
				player.pos.x + player.width / 2,
				player.pos.y + player.height / 2,
				markerSize,
				markerSize,
			);
		}

		// minimap border
		renderer.setGlobalAlpha(0.8);
		renderer.setColor("#ffffff");
		renderer.lineWidth = 2 * screenPx;
		renderer.strokeRect(
			0,
			0,
			MINIMAP_WIDTH / this.zoom,
			MINIMAP_HEIGHT / this.zoom,
		);

		// restore lineWidth
		renderer.lineWidth = savedLineWidth;

		// restore the camera context
		super.postDraw(renderer);
	}

	/**
	 * Cleanup event listeners.
	 */
	override destroy(): void {
		event.off(event.CANVAS_ONRESIZE, this.boundOnResize);
		super.destroy();
	}
}
`,je=`/**
 * melonJS — Platformer (built-in SAT physics) example.
 * Copyright (C) 2011 - 2026 AltByte Pte Ltd — MIT License.
 * See \`packages/examples/LICENSE.md\` for full license + asset credits.
 */
import {
	audio,
	Body,
	collision,
	game,
	input,
	level,
	Rect,
	Sprite,
	timer,
} from "melonjs";
import { gameState } from "../gameState";

export class PlayerEntity extends Sprite {
	dying: boolean;
	multipleJump: number;

	constructor(x, y, settings) {
		// create the sprite using atlas animation frames
		super(x, y, {
			...gameState.texture.getAnimationSettings([
				"walk0001.png",
				"walk0002.png",
				"walk0003.png",
				"walk0004.png",
				"walk0005.png",
				"walk0006.png",
				"walk0007.png",
				"walk0008.png",
				"walk0009.png",
				"walk0010.png",
				"walk0011.png",
			]),
			anchorPoint: { x: 0, y: 0 },
		});

		// add a physic body using the Tiled object dimensions,
		// centered horizontally and bottom-aligned within the sprite frame
		this.body = new Body(
			this,
			new Rect(
				(this.width - settings.width) / 2,
				this.height - settings.height,
				settings.width,
				settings.height,
			),
		);

		// set a "player object" type
		this.body.collisionType = collision.types.PLAYER_OBJECT;

		// player can exit the viewport (jumping, falling into a hole, etc.)
		this.alwaysUpdate = true;

		// walking & jumping speed
		this.body.setMaxVelocity(3, 15);
		this.body.setFriction(0.4, 0);

		this.dying = false;

		this.multipleJump = 1;

		// enable keyboard
		input.bindKey(input.KEY.LEFT, "left");
		input.bindKey(input.KEY.RIGHT, "right");
		input.bindKey(input.KEY.X, "jump", true);
		input.bindKey(input.KEY.UP, "jump", true);
		input.bindKey(input.KEY.SPACE, "jump", true);
		input.bindKey(input.KEY.DOWN, "down");

		input.bindKey(input.KEY.A, "left");
		input.bindKey(input.KEY.D, "right");
		input.bindKey(input.KEY.W, "jump", true);
		input.bindKey(input.KEY.S, "down");

		input.bindGamepad(
			0,
			{ type: "buttons", code: input.GAMEPAD.BUTTONS.FACE_1 },
			input.KEY.UP,
		);
		input.bindGamepad(
			0,
			{ type: "buttons", code: input.GAMEPAD.BUTTONS.FACE_2 },
			input.KEY.UP,
		);
		input.bindGamepad(
			0,
			{ type: "buttons", code: input.GAMEPAD.BUTTONS.DOWN },
			input.KEY.DOWN,
		);
		input.bindGamepad(
			0,
			{ type: "buttons", code: input.GAMEPAD.BUTTONS.FACE_3 },
			input.KEY.DOWN,
		);
		input.bindGamepad(
			0,
			{ type: "buttons", code: input.GAMEPAD.BUTTONS.FACE_4 },
			input.KEY.DOWN,
		);
		input.bindGamepad(
			0,
			{ type: "buttons", code: input.GAMEPAD.BUTTONS.LEFT },
			input.KEY.LEFT,
		);
		input.bindGamepad(
			0,
			{ type: "buttons", code: input.GAMEPAD.BUTTONS.RIGHT },
			input.KEY.RIGHT,
		);

		// map axes
		input.bindGamepad(
			0,
			{ type: "axes", code: input.GAMEPAD.AXES.LX, threshold: -0.5 },
			input.KEY.LEFT,
		);
		input.bindGamepad(
			0,
			{ type: "axes", code: input.GAMEPAD.AXES.LX, threshold: 0.5 },
			input.KEY.RIGHT,
		);
		input.bindGamepad(
			0,
			{ type: "axes", code: input.GAMEPAD.AXES.LY, threshold: -0.5 },
			input.KEY.UP,
		);

		// define a basic walking animation
		this.addAnimation("stand", [{ name: "walk0001.png", delay: 100 }]);
		this.addAnimation("walk", [
			{ name: "walk0001.png", delay: 100 },
			{ name: "walk0002.png", delay: 100 },
			{ name: "walk0003.png", delay: 100 },
		]);
		this.addAnimation("jump", [
			{ name: "walk0004.png", delay: 150 },
			{ name: "walk0005.png", delay: 150 },
			{ name: "walk0006.png", delay: 150 },
			{ name: "walk0002.png", delay: 150 },
			{ name: "walk0001.png", delay: 150 },
		]);

		// set as default
		this.setCurrentAnimation("walk");
	}

	/**
	 * called when added to the game world
	 */
	onActivateEvent() {
		const app = this.parentApp;
		// set the viewport to follow this renderable on both axis, and enable damping
		app.viewport.follow(this, app.viewport.AXIS.BOTH, 0.1);
	}

	/**
	 * update the force applied
	 */
	update(dt) {
		if (input.isKeyPressed("left")) {
			if (this.body.vel.y === 0) {
				this.setCurrentAnimation("walk");
			}
			this.body.force.x = -this.body.maxVel.x;
			this.flipX(true);
		} else if (input.isKeyPressed("right")) {
			if (this.body.vel.y === 0) {
				this.setCurrentAnimation("walk");
			}
			this.body.force.x = this.body.maxVel.x;
			this.flipX(false);
		}

		if (input.isKeyPressed("jump")) {
			this.setCurrentAnimation("jump");
			this.body.jumping = true;
			if (this.multipleJump <= 2) {
				// easy "math" for double jump
				this.body.force.y = -this.body.maxVel.y * this.multipleJump++;
				audio.stop("jump");
				audio.play("jump", false);
			}
		} else {
			if (!this.body.falling && !this.body.jumping) {
				// reset the multipleJump flag if on the ground
				this.multipleJump = 1;
			} else if (this.body.falling && this.multipleJump < 2) {
				// reset the multipleJump flag if falling
				this.multipleJump = 2;
			}
		}

		if (this.body.force.x === 0 && this.body.force.y === 0) {
			this.setCurrentAnimation("stand");
		}

		// check if we fell into a hole
		if (!this.inViewport && this.getBounds().top > game.renderer.height) {
			const app = this.parentApp;
			// if yes reset the game
			app.world.removeChild(this);
			app.viewport.fadeIn("#fff", 150, () => {
				audio.play("die", false);
				level.reload();
				app.viewport.fadeOut("#fff", 150);
			});
			return true;
		}

		// check if we moved (an "idle" animation would definitely be cleaner)
		if (this.body.vel.x !== 0 || this.body.vel.y !== 0 || this.isFlickering()) {
			super.update(dt);
			return true;
		}
		return false;
	}

	/**
	 * collision handler
	 */
	onCollision(response, other) {
		switch (other.body.collisionType) {
			case collision.types.WORLD_SHAPE:
				// Simulate a platform object
				if (other.type === "platform") {
					if (
						this.body.falling &&
						!input.isKeyPressed("down") &&
						// Shortest overlap would move the player upward
						response.overlapV.y > 0 &&
						// The velocity is reasonably fast enough to have penetrated to the overlap depth
						~~this.body.vel.y >= ~~response.overlapV.y
					) {
						// Disable collision on the x axis
						response.overlapV.x = 0;
						// Respond to the platform (it is solid)
						return true;
					}
					// Do not respond to the platform (pass through)
					return false;
				}

				// Custom collision response for slopes
				if (other.type === "slope") {
					// Always adjust the collision response upward
					response.overlapV.y = Math.abs(response.overlap);
					response.overlapV.x = 0;

					// Respond to the slope (it is solid)
					return true;
				}
				break;

			case collision.types.ENEMY_OBJECT:
				if (!other.isMovingEnemy) {
					// spike or any other fixed danger
					this.body.vel.y -= this.body.maxVel.y * timer.tick;
					this.hurt();
				} else {
					// a regular moving enemy entity
					if (response.overlapV.y > 0 && this.body.falling) {
						// jump
						this.body.vel.y -= this.body.maxVel.y * 1.5 * timer.tick;
					} else {
						this.hurt();
					}
					// Not solid
					return false;
				}
				break;

			default:
				// Do not respond to other objects (e.g. coins)
				return false;
		}

		// Make the object solid
		return true;
	}

	/**
	 * ouch
	 */
	hurt() {
		if (!this.isFlickering()) {
			// tint to red and flicker
			this.tint.setColor(255, 192, 192);
			this.flicker(750, () => {
				// clear the tint once the flickering effect is over
				this.tint.setColor(255, 255, 255);
			});

			// flash the screen and shake the camera
			this.parentApp.viewport.fadeIn("#FFFFFF", 75);
			this.parentApp.viewport.shake(4, 200);
			audio.play("die", false);
		}
	}
}
