		this.addAnimation("jump", [
			{ name: "walk0004.png", delay: 150 },
			{ name: "walk0005.png", delay: 150 },
			{ name: "walk0006.png", delay: 150 },
			{ name: "walk0002.png", delay: 150 },
			{ name: "walk0001.png", delay: 150 },
		]);

