`,mt=`/**
 * melonJS — Pool (Matter) example: procedural sound effects.
 * Copyright (C) 2011 - 2026 AltByte Pte Ltd — MIT License.
 * See \`packages/examples/LICENSE.md\` for full license + asset credits.
 *
 * Five thin wrappers around \`audio.tone\` — no asset files, no loaders.
 * Each maps a gameplay event to a single envelope-shaped tone:
 *   - playStrike       cue-on-ball thwack on release
 *   - playBallClick    classic billiards click on ball-ball contact
 *   - playRailBounce   softer thud on cushion bounce
 *   - playPocketDrop   two-partial ring on a successful pot
 *   - playScratch      descending fail tone when the cue ball is pocketed
 *
 * Most wrappers take a normalised \`velocity\` factor in \`[0, 1]\` so the
 * gain scales with impact intensity, plus a \`pan\` in \`[-1, 1]\` so a
 * shot on the left rail clacks left and a shot on the right rail
 * clacks right — same trick as the plinko peg pans.
 */

import { audio } from "melonjs";
import { VIEWPORT_W } from "./constants";

/**
 * Convert a world x-coordinate to a stereo pan in \`[-1, 1]\`. Centre of
 * the table is 0; left edge is -1, right edge is 1.
 */
export const panForX = (x: number): number => {
	const normalised = (x / VIEWPORT_W) * 2 - 1;
	return Math.max(-1, Math.min(1, normalised));
};

/**
 * Normalise a matter body's per-step velocity magnitude into a \`[0, 1]\`
 * factor for gain scaling. Pool ball velocities at full break are
 * roughly in the 8–12 px/step range; we cap at 10 so a hard break
 * tops out at gain factor 1 and lighter contacts scale linearly down.
 */
export const velocityFactor = (speed: number): number => {
	return Math.max(0, Math.min(1, speed / 10));
};

/** Soft wood/leather "thock" when the cue tip strikes the cue ball. */
export const playStrike = (power: number, pan = 0): void => {
	audio.tone({
		freq: 350,
		duration: 0.1,
		gain: 0.18 * Math.max(0.2, power),
		pan,
		pitchSlide: 0.3,
	});
};

/**
 * Phenolic-resin click on ball-ball contact — two partials (mid body +
 * upper bite) with random jitter so a multi-ball break stays granular,
 * very short duration so it reads as a dry click without lingering ring.
 */
export const playBallClick = (velocity: number, pan = 0): void => {
	const v = velocityFactor(velocity);
	if (v < 0.05) return; // skip vanishingly soft taps
	const jitter = Math.random();
	audio.tone({
		freq: [420 + jitter * 80, 820 + jitter * 120],
		duration: 0.035,
		gain: 0.12 * v,
		pan,
		pitchSlide: 0.5,
	});
};

/** Softer low thud on cushion bounces. Distinguishable from ball-ball
 *  by frequency band (mid-low vs upper-mid). */
export const playRailBounce = (velocity: number, pan = 0): void => {
	const v = velocityFactor(velocity);
	if (v < 0.05) return;
	audio.tone({
		freq: 350,
		duration: 0.1,
		gain: 0.12 * v,
		pan,
		pitchSlide: 0.5,
	});
};

/** Satisfying two-partial ring when a numbered ball drops in a pocket. */
export const playPocketDrop = (pan = 0): void => {
	audio.tone({
		freq: [440, 660],
		duration: 0.25,
		gain: 0.18,
		pan,
	});
};

/** Descending sawtooth "buzzer" when the cue ball gets pocketed. */
export const playScratch = (pan = 0): void => {
	audio.tone({
		freq: 400,
		duration: 0.4,
		wave: "sawtooth",
		gain: 0.15,
		pan,
		pitchSlide: 0.3,
	});
};
`,ht=`/**
 * melonJS — Pool (Matter) example: tuning constants.
 * Copyright (C) 2011 - 2026 AltByte Pte Ltd — MIT License.
 * See \`packages/examples/LICENSE.md\` for full license + asset credits.
 *
 * All "feel" values live here so the user can iterate on \`frictionAir\`
 * (table drag), \`restitution\` (bounce), and \`STRIKE_FORCE_SCALE\` (how
 * hard a max-power strike hits) in one place rather than chasing them
 * through entities.
 *
 * Pocket and rail GEOMETRY (per-element position + size) is **not**
 * here — it's in \`entities/pocket.ts\` (\`POCKET_POSITIONS\`) and
 * \`entities/table.ts\` (\`RAIL_RECTS\`), each as an explicit row-per-piece
 * table so a single off pocket or rail can be tuned without cascading
 * into the others.
 */

// viewport — matches the table.png native dimensions (1280×723) so the
// table sprite renders 1:1 without scaling distortion. \`scaleMethod:
// "fit"\` in the Application config then scales the whole canvas to the
// browser window while preserving aspect ratio.
export const VIEWPORT_W = 1280;
export const VIEWPORT_H = 723;

// Play boundaries are measured to the **dark-green felt edge** in the
// table sprite — NOT the brown rail and NOT the light-green cushion
// strip. Balls live inside this rectangle in world coordinates.
export const PLAY_LEFT = 107;
export const PLAY_RIGHT = 1180;
export const PLAY_TOP = 90;
export const PLAY_BOTTOM = 635;
export const PLAY_W = PLAY_RIGHT - PLAY_LEFT;
export const PLAY_H = PLAY_BOTTOM - PLAY_TOP;
export const PLAY_MIDX = (PLAY_LEFT + PLAY_RIGHT) / 2;

// ball geometry — chosen so a 5-row rack fits the table comfortably
// (rack width ≈ 5 × 2 × BALL_RADIUS ≈ 160 px out of ~880 play width)
export const BALL_RADIUS = 16;

// physics tuning — TUNE_ME interactively
// Real pool balls slide first then roll — sliding friction is ~3× rolling
// friction. Matter only models one \`frictionAir\`, so we swap between the
// two values in \`Ball.update\` based on current speed: above
// \`ROLL_TRANSITION_VEL\` the ball reads as sliding (high drag), below it
// rolls cleanly (low drag). The transition is what makes break shots
// look like the cue ball "settles" into a roll partway down the table
// instead of decelerating uniformly.
/** rolling friction air drag — applied below ROLL_TRANSITION_VEL */
export const BALL_FRICTION_AIR_ROLL = 0.003;
/** sliding friction air drag — applied above ROLL_TRANSITION_VEL */
export const BALL_FRICTION_AIR_SLIDE = 0.018;
/** speed (px/frame) at which sliding transitions to rolling */
export const ROLL_TRANSITION_VEL = 1.5;
// rail bounciness. 1.0 = perfectly elastic; lower = energy loss per bounce.
export const RAIL_RESTITUTION = 0.85;
// ball-on-ball bounciness — pool balls are very elastic in reality.
export const BALL_RESTITUTION = 0.92;
// ball density — keep all 16 balls equal so collisions transfer momentum
// the way you'd expect from break shots.
export const BALL_DENSITY = 0.01;

// strike (cue) tuning
// drag-distance (px) that corresponds to max-power. Drags beyond this
// cap to MAX_DRAG so the player can't apply absurd velocities.
export const MAX_DRAG = 200;
// peak impulse magnitude applied at max drag. With density=0.01 and
// radius=16, ball mass works out to ~8; matter-js applyImpulse adds
// \`impulse / mass\` directly to velocity, so a max-power strike of 240
// gives a delta-V of ~30 px/frame — break-shot territory, snappy enough
// that the rack actually scatters. Lower if you want softer strikes;
// higher and you risk tunneling on the corner pocket sensors.
export const STRIKE_FORCE_SCALE = 240;
`,gt=`/**
 * melonJS — Pool (Matter) example: Application bootstrap.
 * Copyright (C) 2011 - 2026 AltByte Pte Ltd — MIT License.
 * See \`packages/examples/LICENSE.md\` for full license + asset credits.
 *
 * Wires up the matter-physics adapter (zero-gravity, top-down), the
 * camera vignette post-effect, the debug-panel plugin, and kicks off
 * the asset preload + state transition into \`PlayScreen\`.
 */
import { DebugPanelPlugin } from "@melonjs/debug-plugin";
import { MatterAdapter } from "@melonjs/matter-adapter";
import {
	Application,
	game,
	loader,
	plugin,
	state,
	VignetteEffect,
	video,
} from "melonjs";
import { VIEWPORT_H, VIEWPORT_W } from "./constants";
import { PlayScreen } from "./play";
import { resources } from "./resources";

export const createGame = async () => {
	// Pool table is top-down, so we run matter with **zero gravity** —
	// frictionAir on each ball provides the table-felt drag that brings
	// balls to rest. No vertical-axis force needed.
	const _app = new Application(VIEWPORT_W, VIEWPORT_H, {
		parent: "screen",
		scaleMethod: "fit",
		renderer: video.AUTO,
		subPixel: false,
		highPrecisionShader: false,
		// Anti-aliasing smooths the painted edges on the table sprite,
		// the procedural cue stick, and the strokes on the aim line +
		// ghost ball outline. The viewport scales to fit the browser
		// window so sub-pixel positions are unavoidable; without AA the
		// rail/pocket edges shimmer when the canvas size doesn't land
		// on an integer multiple of the source 1280×723.
		antiAlias: true,
		// Run matter with 2 physics substeps per frame. At max-power break
		// shots the cue ball moves ~30 px/frame and BALL_RADIUS=16, so a
		// single-step narrow phase can miss a ball-on-ball or ball-on-
		// rail contact and the cue tunnels through. Two substeps caps
		// per-tick motion at ~15 px (< 1 radius) at the cost of running
		// the solver twice — pool only has 16 bodies, so the perf hit
		// is unmeasurable.
		physic: new MatterAdapter({ gravity: { x: 0, y: 0 }, subSteps: 2 }),
	});
	await _app.init();

	// Vignette as a camera post-effect — uses the engine's built-in
	// \`VignetteEffect\` shader (WebGL fragment pass) which darkens UV
	// edges procedurally. Way cleaner than a fullscreen overlay
	// renderable and resolution-independent. \`strength=0.18\` is subtle
	// enough that the corner pockets stay readable; \`size=22\` keeps the
	// dark falloff confined to the outer ~25% of the viewport.
	_app.viewport.shader = new VignetteEffect(game.renderer, {
		strength: 0.18,
		size: 22.0,
	});

	// register the debug plugin — press 'S' in-game to toggle the panel
	// (collision bodies, FPS, draw-call counts, etc.)
	plugin.register(DebugPanelPlugin, "debugPanel");

	// allow cross-origin asset loading (same as the matter platformer)
	loader.setOptions({ crossOrigin: "anonymous" });

	loader.preload(resources, () => {
		state.set(state.PLAY, new PlayScreen());
		state.change(state.PLAY);
	});
};
